    faqCategoryGeneral: "Všeobecné",
    faqCategoryPrice: "Ceny a financovanie",
    faqCategoryDelivery: "Dodanie a montáž",
    faqCategoryConstruction: "Výstavba",
    faqCategoryWarranty: "Záruka a servis",
    faqCategoryEnergy: "Energia a úspory",
    faqNoResults: "Nenašli sa žiadne výsledky",
    faqStillHaveQuestions: "Stále máte otázky?",
    faqContactUs: "Neváhajte nás kontaktovať telefonicky alebo emailom. Radi vám pomôžeme.",
    
    faq1Q: "Čo je to modulárny dom?",
    faq1A: "Modulárny dom je moderný typ domu, ktorý sa vyrába v továrni vo forme kompletných modulov a potom sa transportuje a osadzuje na pripravený pozemok. Výhodou je rýchlosť výstavby a vysoká kvalita vďaka kontrolovanému prostrediu výroby.",
    faq2Q: "Aký je rozdiel medzi modulárnym a montovaným domom?",
    faq2A: "Modulárny dom prichádza vo forme kompletných modulov, ktoré sa len osadiť a prepojiť. Montovaný dom prichádza ako súprava konštrukčných prvkov, ktoré sa na mieste zmontujú. Oba typy ponúkame.",
    faq3Q: "Potrebujem stavebné povolenie?",
    faq3A: "Áno, pre rodinný dom je potrebné stavebné povolenie. Pomôžeme vám s celým procesom vrátane projektu a vybavenia povolenia. Pre rekreačné stavby sa môžu pravidlá líšiť podľa veľkosti a účelu.",
    
    faq4Q: "Aká je celková cena domu?",
    faq4A: "Celková cena závisí od konfigurácie, veľkosti a výberu doplnkov. V našom konfigurátore vidíte presnú cenu vrátane všetkých vybraných položiek. Základné ceny začínajú od cca 30 000 EUR.",
    faq5Q: "Je možné financovanie formou hypotéky?",
    faq5A: "Áno, naše domy je možné financovať klasickou hypotékou. Spolupracujeme s finančnými poradcami, ktorí vám pomôžu vybrať najvýhodnejší úver.",
    faq6Q: "Sú v cenách zahrnuté všetky náklady?",
    faq6A: "V konfigurátore vidíte detailný rozpis všetkých položiek. Základná cena obsahuje dom v zvolenej konfigurácii. Doprava, montáž, základy a prípojky sa počítajú samostatne podľa konkrétnych podmienok vášho pozemku.",
    
    faq7Q: "Ako dlho trvá dodanie domu?",
    faq7A: "Dom odovzdávame do 12 týždňov od vydaného stavebného povolenia a dokončení základov.",
    faq8Q: "Ako prebieha montáž?",
    faq8A: "Modulárne domy sa osadzujú pomocou autodźera na pripravené základy. Montáž trvá 1-2 dni. Montované domy sa skladajú na mieste, montáž trvá 5-10 dní podľa veľkosti.",
    faq9Q: "Aké základy sú potrebné?",
    faq9A: "Záleží na type domu a pôdnych podmienkach. Ponúkame zemné skrutky, betónové pätky, základovú dosku alebo pásové základy. Po geodetickej analýze vášho pozemku navrhneme najvhodnejšie riešenie.",
    
    faq10Q: "Je možné dom prispôsobiť?",
    faq10A: "Áno, ponúkame široké možnosti prispôsobenia - od rozloženia miestností, cez výber materiálov až po farby a doplnky. Všetko môžete nastaviť v konfigurátore alebo konzultovať s našimi odborníkmi.",
    faq11Q: "Aký je životnosť modulárneho domu?",
    faq11A: "Pri správnej údržbe má modulárny dom životnosť viac ako 80 rokov, rovnako ako klasický murovaný dom. Konštrukcia je certifikovaná a spĺňa všetky normy EU.",
    faq12Q: "Sú domy vhodné na celoročné bývanie?",
    faq12A: "Áno, všetky naše domy sú štandardne navrhnuté na celoročné bývanie s kvalitnou izoláciou. Ponúkame aj konfigurácie s energetickým certifikátom A0 pre minimálne náklady na vykurovanie.",
    
    faq13Q: "Akú záruku poskytujete?",
    faq13A: "Poskytujeme štandardnú záruku 5 rokov na konštrukciu a 2 roky na technológie. Výrobcovia poskytujú dodatočné záruky na jednotlivé komponenty.",
    faq14Q: "Kdo sa stará o servis a údržbu?",
    faq14A: "Ponúkame pravidelnú údržbu a servis. Väčšinu bežných úkonov však môžete robiť sami, podobne ako pri klasickom dome. Pri technických problémoch sme vám k dispozícii.",
    
    faq15Q: "Aké sú náklady na vykurovanie?",
    faq15A: "Vďaka kvalitnej izolácii a možnosti inštalácie tepelného čerpadla sú náklady na vykurovanie nízke. Dom s certifikátom A0 má ročné náklady približne 200-400 EUR pri ploche 80-100 m².",
    faq16Q: "Môžem získať energetický certifikát A0?",
    faq16A: "Áno, v konfigurátore môžete vybrať všetky potrebné komponenty pre dosiahnutie energetickej triedy A0 - zosilnenú izoláciu, tepelné čerpadlo, rekuperáciu a kvalitné okná.",
    
    // Modular Homes Bratislava page
    modularHomesBratislava: "Modulárne domy Bratislava",
    modularHomesBratislavaSubtitle: "Rýchla výstavba kvalitných modulárnych domov v Bratislave a okolí",
    modularHomesBratislavaMetaDesc: "Modulárne domy v Bratislave - rýchla výstavba, priame ceny od výrobcu, komplexné služby. Viac ako 700 realizovaných domov. Kontaktujte nás na +421 905 138 124",
    whyModularHomesBratislava: "Prečo modulárne domy v Bratislave?",
    bratislavaIntro1: "Bratislava a jej okolie je ideálnym miestom pre modulárne domy. Vysoké ceny nehnuteľností a nedostatok pozemkov robia z modulárnej výstavby rýchle a cenovo dostupné riešenie.",
    bratislavaIntro2: "Naše modulárne domy možno postaviť na väčšine pozemkov v Bratislavskom kraji, vrátane mestských častí ako Rača, Vajnory, Záhorská Bystrica a ďalších.",
    bratislavaFast: "Váš dom môže byť hotový za 3-4 mesiace od objednávky. Ideálne riešenie pre rýchle sťahovanie.",
