    modularAdvantage: "Modular construction advantage:",
    modularAdvantageDesc: "This house is the ideal choice for those looking for practical but stylish living with easy installation and immediate readiness for use. Thanks to thoughtful design, quality materials and customization options, it is suitable both for smaller families and for people looking for a quiet place to relax outside the city.\n\nThe price does not include transport, foundations, external connections or crane services needed to unload the house.\n\nAll our houses are designed so that they can be easily transported throughout the EU in a fully completed state. After delivery, the customer just unloads the house from the crane, mounts it on a prepared foundation (single-module houses do not require a solid foundation), connects utilities and can immediately start using it. The only thing left is to bring your favorite furniture and equipment according to your own taste.\n\nThese houses are the ideal choice for families looking for a practical, immediately habitable solution with the possibility of mobility. They are also a great alternative for seniors who long for a cozy place outside the city – ideal for relaxation and comfortable living.\n\nThanks to quality materials, efficient solutions and simple layout, this house is designed to meet the needs of everyone looking for a comfortable and yet accessible way of living.\n\nThe internal division of rooms, type of exterior plaster and interior wall cladding can be freely changed.",
    
