    importantBasePriceExcludes: "FONTOS - Az alapmodell ára konfigurátor nélkül NEM tartalmazza:",
    deliveryTransport: "Szállítás és fuvarozás",
    orderInConfigurator: "megrendelhető a konfigurátorban",
    singleModuleNoFoundations: "egymodulos házak nem igényelnek \"téglából\" készült alapot",
    externalConnections: "Külső csatlakozások",
