    requiredForPlacement: "szükséges a ház telekre helyezéséhez",
    modularAdvantage: "Moduláris építés előnye:",
    modularAdvantageDesc: "Ez a ház ideális választás azok számára, akik praktikus, de stílusos lakhatást keresnek egyszerű telepítéssel és azonnali használatra való készséggel. Az átgondolt tervezésnek, minőségi anyagoknak és a testreszabási lehetőségeknek köszönhetően alkalmas kisebb családok és olyan emberek számára is, akik a városon kívül keresnek nyugodt helyet a pihenéshez.\n\nAz ár nem tartalmazza a szállítást, az alapokat, a külső csatlakozásokat és a daru szolgáltatásait, amelyek a ház kirakodásához szükségesek.\n\nMinden házunk úgy van megtervezve, hogy az EU egész területén könnyen szállítható legyen teljesen kész állapotban. Kézbesítés után az ügyfél csak kirakodja a házat a daruból, az előkészített alapra szereli (az egymodulos házakhoz nem szükséges szilárd alap), csatlakoztatja a közműveket, és azonnal használatba veheti. Az egyetlen dolog, ami hátra van, hogy behozza kedvenc bútorát és berendezését saját ízlése szerint.\n\nEzek a házak ideális választást jelentenek olyan családok számára, akik gyakorlatias, azonnal lakható megoldást keresnek mobilitási lehetőséggel. Ugyanakkor nagyszerű alternatívát jelentenek az idősek számára, akik a városon kívül vágynak egy hangulatos helyre – ideális pihenésre és kényelmes életre.\n\nA minőségi anyagoknak, hatékony megoldásoknak és egyszerű elrendezésnek köszönhetően ez a ház úgy lett megtervezve, hogy megfeleljen mindenki igényeinek, aki kényelmes és mégis elérhető életmódot keres.\n\nA szobák belső felosztása, a külső vakolat típusa és a belső falburkolat szabadon változtatható.",
    
